/*selectMasterMpRqBuyerQuotationSendPopList*/ SELECT RFQ.BUYER, RFQ.QUOTATION_NO, RFQ.QUOTATION_SEQ, RFQ.REVISION, RFQ.BUYER_ITEM_NO_STATUS, RFQ.BUYER_NAME_LOC AS BUYER_NAME, RFQ.BUYER_ITEM_NO, RFQ.DESCRIPTION, RFQ.DESCRIPTION AS ORG_DESCRIPTION, RFQ.MAKER_NAME, RFQ.UNIT_MEASURE, RFQ.ATOB_UNIT_PRICE, RFQ.BUYER_TARGET_PRICE, RFQ.SPECIFICATION, RFQ.SPECIFICATION AS ORG_SPECIFICATION, RFQ.STOA_LIST_PRICE, RFQ.LEAD_TIME, RFQ.AGENT_NAME_LOC AS AGENT_NAME, RFQ.ORIGIN_NAME_LOC AS ORIGIN_NAME, RFQ.ORIGIN_NAME AS ORIGIN_CODE, RFQ.AGENT, RFQ.ORG_CODE, DECODE(RFQ.BUYER_ITEM_NO_STATUS, '신규', (SELECT MAX(CONTRACT_NO) FROM ICOMCQHD WHERE BUYER = (SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE = RFQ.BUYER) AND STATUS != 'D' AND CONTRACT_TO_DATE >= TO_CHAR(SYSDATE, 'YYYYMMDD')), RFQ.CONTRACT_NO) AS CONTRACT_NO, RFQ.CONTRACT_SEQ, RFQ.PROCESS_TYPE, RFQ.REG_ITEM_NO, RFQ.ITEM_QTY, RFQ.IMAGE_KEY, RFQ.ITEM_DETAIL_DESC, RFQ.SEND_FLAG, RFQ.ATOS_END_DATE, RFQ.ATOS_END_TIME, RFQ.AGENT_OPEN_FLAG, RFQ.SELLER_IMAGE_KEY, RFQ.PM_FLAG AS OPM_FLAG, RFQ.PROCESS_TEXT, RFQ.MAKER_PART_NO, RFQ.BELOW_COMORG_NAME, RFQ.BELOW_COMORG_CODE, RFQ.CATEG_NAME, RFQ.CMS_CATEG_ID, BYCA.CATEG_NAME AS BUYER_CATEG_NAME, RFQ.CATEGORY_NO AS BUYER_CATEG_CODE, RFQ.ORIGIN_AGENT_NAME, RFQ.ORIGIN_AGENT, RFQ.BUYER_ITEM_NO_STATUS, RFQ.ATOB_REMARK, RFQ.MAKER_CODE, RFQ.CMS_CATLG_ID, RFQ.ITEM_NO, DECODE(RFQ.BUYER_RATE_GAIN, 0, 'N','Y') AS RATE_FLAG, RFQ.INIT_PROCESS_TYPE, RFQ.INIT_PROCESS_NAME, RFQ.INIT_WAREHOUSE_CODE, RFQ.INIT_WAREHOUSE_NAME, RFQ.INIT_BELOW_COMORG_CODE, RFQ.INIT_BELOW_COMORG_NAME, RFQ.CMS_DESCRIPTION, RFQ.CMS_SPECIFICATION, RFQ.CMS_UNIT_MEASURE, RFQ.CMS_MAKER_NAME, RFQ.CMS_ORIGIN_NAME, NVL(RFQ.CMS_MAKER_PART_NO,'') AS CMS_MAKER_PART_NO, RFQ.CMS_MAKER_CODE, RFQ.CMS_ORIGIN_CODE, RFQ.ADMIN_TARGET_PRICE , '사업팀' AS TEAM , KEP_RATE , RFQ.IMGFILE_NAME ,F_GET_PM_REASON(RFQ.BUYER,RFQ.QUOTATION_NO,RFQ.QUOTATION_SEQ,RFQ.REVISION)||' '||RFQ.BID_SUCCESS_REASON AS PM_REASON ,(RFQ.ATOB_UNIT_PRICE * RFQ.ITEM_QTY ) TOTAL_UNIT_PRICE ,RFQ.ITEM_MAKE_TYPE ,RFQ.MOQ_QTY ,RFQ.CATEGORY_CHOICE_TYPE ,RFQ.RFQ_IMG_FLAG ,RFQ.RFQ_IMG_TYPE ,RFQ.IMGFILE_DIR ,RFQ.IMGFILE_NAME ,DECODE(RFQ.IMGFILE_NAME,'','0','1') AS IMGFILE_NAME_IMG ,RFQ.STOA_REMARK ,DECODE(RFQ.STOA_REMARK,'','6','5') AS STOA_REMARK_IMG ,RFQ.TAX_TYPE ,RFQ.DESCRIPTION_ENG ,RFQ.SPECIFICATION_ENG ,DECODE(RFQ.BUYER_ITEM_NO_STATUS, '신규', RFQ.EXP_CODE, '') AS EXP_CODE ,DECODE(RFQ.BUYER_ITEM_NO_STATUS, '신규', (SELECT CH.EXP_CUR FROM KEP_CURRENCY_HD CH WHERE CH.EXP_CODE =RFQ.EXP_CODE),'') AS EXP_CUR ,DECODE(RFQ.BUYER_ITEM_NO_STATUS, '신규',(SELECT CH.EXP_CUR_PRICE FROM KEP_CURRENCY_HD CH WHERE CH.EXP_CODE =RFQ.EXP_CODE),'') AS EXP_CUR_PRICE ,DECODE(RFQ.BUYER_ITEM_NO_STATUS, '신규', F_GET_EXCHANGE_RATE(RFQ.BUYER,RFQ.ATOB_UNIT_PRICE,RFQ.EXP_CODE,'01'),'') AS EXP_FOR_UNIT_PRICE ,DECODE(RFQ.BUYER_ITEM_NO_STATUS, '신규', F_GET_EXCHANGE_RATE(RFQ.BUYER,RFQ.ATOB_UNIT_PRICE,RFQ.EXP_CODE,'02'),'') AS EXP_INC_EXPENSE ,DECODE(RFQ.BUYER_ITEM_NO_STATUS, '신규', F_GET_EXCHANGE_RATE(RFQ.BUYER,RFQ.ATOB_UNIT_PRICE,RFQ.EXP_CODE,'03'),'') AS EXP_KR_UNIT_PRICE ,RFQ.PLANT ,KEP.F_GET_SELL_CLOSE_DATE(RFQ.BUYER) AS TO_DATE ,TO_CHAR(LAST_DAY(SYSDATE+365),'YYYYMMDD') AS BUY_CLOSE_DATE ,F_GET_SELLER_AREA_TEXT(RFQ.BUYER, RFQ.SELLER_AREA) AS SELLER_AREA ,F_GET_BUYER_PLANT_TEXT(RFQ.BUYER, RFQ.PLANT) AS PLANT_NAME ,NVL2 (TRIM(RFQ.IMGFILE_DIR||RFQ.IMGFILE_NAME), 'https://keps3.koreab2b.com/'||RFQ.IMGFILE_DIR|| '/' ||RFQ.IMGFILE_NAME, '/resources/images/icon_emptyimg.gif') AS IMG , (SELECT MAX(B.TEXT1) FROM MIS_BUYER_MNG A, ICOMCOD2 B WHERE A.YEAR = TO_CHAR(SYSDATE,'YYYY') AND A.STATUS != 'O' AND A.KEP_DEPT = B.CODE AND B.COMPANY_CODE ='KRKORE0001' AND B.TYPE ='C001' AND A.BUYER = RFQ.BUYER) AS MNG_DEPT_NM , RFQ.ASSIGN_AGENT_CODE , RFQ.BTOA_NEGO_PRICE , RFQ.BTOA_USER_ID FROM ( SELECT A.BUYER, A.QUOTATION_NO, A.QUOTATION_SEQ, A.REVISION, BP.COM_NAME_LOC AS BUYER_NAME_LOC, A.BUYER_ITEM_NO, A.DESCRIPTION, MK.TEXT1 AS MAKER_NAME, A.UNIT_MEASURE, NVL(B.ATOB_UNIT_PRICE, 0) AS ATOB_UNIT_PRICE, NVL(A.BUYER_TARGET_PRICE, 0) AS BUYER_TARGET_PRICE, NVL(A.ADMIN_TARGET_PRICE, 0) AS ADMIN_TARGET_PRICE, A.SPECIFICATION, NVL(B.STOA_LIST_PRICE, 0) STOA_LIST_PRICE, B.LEAD_TIME, AP.COM_NAME_LOC AGENT_NAME_LOC, OG.TEXT2 AS ORIGIN_NAME_LOC, NVL(A.ORIGIN_CODE, '') ORIGIN_NAME, B.AGENT, BP.BYCA_COMORG_CODE ORG_CODE, A.REG_ITEM_NO, A.ITEM_QTY, NVL(A.IMAGE_KEY,'') AS IMAGE_KEY, NVL(A.ITEM_DETAIL_DESC,'') AS ITEM_DETAIL_DESC, DECODE(NVL(NVL((SELECT COUNT(QT.AGENT) FROM KEPQTDT QT WHERE QT.BUYER = A.BUYER AND QT.QUOTATION_NO = A.QUOTATION_NO AND QT.QUOTATION_SEQ = A.QUOTATION_SEQ AND QT.REVISION = A.REVISION AND QT.STATUS IN ('C','R') GROUP BY QT.BUYER , QT.QUOTATION_NO , QT.QUOTATION_SEQ , QT.REVISION),0) - NVL((SELECT COUNT(B.AGENT) FROM KEPQTDT B WHERE B.BUYER = A.BUYER AND B.QUOTATION_NO = A.QUOTATION_NO AND B.QUOTATION_SEQ = A.QUOTATION_SEQ AND B.REVISION = A.REVISION AND B.SEL_USER_ID IS NOT NULL AND B.STATUS IN ('C','R') GROUP BY B.BUYER , B.QUOTATION_NO , B.QUOTATION_SEQ , B.REVISION),0),0), 0, 'Y','N') AS SEND_FLAG, B.ATOS_END_DATE, B.ATOS_END_TIME, A.AGENT_OPEN_FLAG, NVL(A.SELLER_IMAGE_KEY,'') SELLER_IMAGE_KEY, CASE WHEN A.BUYER = 'KRKOLO0001' THEN 'PM' /* 코오롱인더스트리(주)구미공장 */ WHEN A.BUYER = 'KRKOLO0002' THEN 'PM' /* 코오롱인더스트리(주)경산공장 */ WHEN A.BUYER = 'KRKOLO0003' THEN 'PM' /* 코오롱인더스트리(주)김천공장 */ WHEN A.BUYER = 'KRDOOD0001' THEN 'PM' /* 두산중공업(주) */ WHEN NVL(B.ITEM_QTY,0)* NVL(B.STOA_LIST_PRICE,0) >= 500000 THEN 'PM' WHEN A.PRE_GR_FLAG = 'Y' THEN 'PM' WHEN B.BID_SUCCESS_CODE != 'BS01' THEN 'PM' WHEN (SELECT COUNT(*) FROM KEPQTDT WHERE BUYER = B.BUYER AND QUOTATION_NO = B.QUOTATION_NO AND QUOTATION_SEQ = B.QUOTATION_SEQ AND REVISION = B.REVISION AND AGENT_REVISION = B.AGENT_REVISION AND STATUS = 'C' AND NVL(STOA_LIST_PRICE,0) > 0 AND STOA_DATE IS NOT NULL
) <= 1 THEN 'PM' WHEN KEP.F_GET_RQDT_PM_FLAG(A.BUYER, A.SG_ID, A.KEP_RATE) = 'Y' THEN 'PM' ELSE 'NO' END AS PM_FLAG, NVL(CQDT.CONTRACT_NO,'') AS CONTRACT_NO, NVL(CQDT.CONTRACT_SEQ,'') AS CONTRACT_SEQ, NVL(CQDT.PROCESS_TYPE,'') AS PROCESS_TYPE, NVL(CQDT.BELOW_COMORG_CODE,'') AS BELOW_COMORG_CODE, PT.TEXT2 AS PROCESS_TEXT, CASE WHEN CQDT.BELOW_COMORG_CODE = 'ALL' THEN '전체' ELSE (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = CQDT.BELOW_COMORG_CODE) END AS BELOW_COMORG_NAME, CQDT.MAKER_PART_NO AS CQDT_MAKER_PART_NO, NVL(B.SELLER_ITEM_NO, CQDT.ITEM_NO) AS ITEM_NO, CQDT.ORIGIN_AGENT, OA.COM_NAME_LOC AS ORIGIN_AGENT_NAME, DECODE( (SELECT COUNT(BUYER_ITEM_NO) FROM ICOMBYIT WHERE BUYER = BP.BYCA_COMORG_CODE AND BUYER_ITEM_NO = B.BUYER_ITEM_NO ), 0, '신규', DECODE( (SELECT COUNT(BUYER_ITEM_NO) FROM ICOMCQDT WHERE BUYER = BP.BYCA_COMORG_CODE AND BUYER_ITEM_NO = B.BUYER_ITEM_NO AND BELOW_COMORG_CODE = B.BUYER AND STATUS IN ('C','R','S')),0,'신규', DECODE((SELECT COUNT(BUYER_ITEM_NO) FROM ICOMBYIT WHERE BUYER = BP.BYCA_COMORG_CODE AND BUYER_ITEM_NO = B.BUYER_ITEM_NO AND PRODUCT_CLOSE_FLAG = 'S'),0,'기등록', DECODE(A.ATOB_SEND_FLAG, 'N','기등록','Y', '구매사NEGO건')))) AS BUYER_ITEM_NO_STATUS, CASE WHEN BYIT.CATEGORY_NO IS NOT NULL THEN BYIT.CATEGORY_NO WHEN A.CATEGORY_NO IS NOT NULL THEN A.CATEGORY_NO ELSE (SELECT MAX(BYCA.STD_CATEG_ID) FROM ICOMBYCA BYCA WHERE BYCA.COM_CODE = BP.BYCA_COMORG_CODE AND BYCA.CMS_CATEG_ID = A.CMS_CATEG_ID) END AS CATEGORY_NO, A.ITEM_GUBUN, A.ATOB_REMARK, CE.CATEG_NAME, A.CMS_CATEG_ID, A.MAKER_CODE, A.CMS_CATLG_ID, (SELECT COUNT(*) FROM KEPQTDT QTDT WHERE QTDT.BUYER = B.BUYER AND QTDT.QUOTATION_NO = B.QUOTATION_NO AND QTDT.QUOTATION_SEQ= B.QUOTATION_SEQ AND QTDT.REVISION = B.REVISION AND QTDT.STATUS IN ('C','R') AND NVL(QTDT.STOA_LIST_PRICE,0) ^= 0 AND NVL(QTDT.ATOB_UNIT_PRICE,0) ^= 0 AND QTDT.BID_SUCCESS_FLAG = 'Y' AND EXISTS (SELECT 'X' FROM KEP_BUYER_RATE C WHERE TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN C.FROM_DATE AND C.TO_DATE AND C.BUYER = QTDT.BUYER AND C.RATE*.9 >= (1-QTDT.STOA_LIST_PRICE/QTDT.ATOB_UNIT_PRICE)*100)) AS BUYER_RATE_GAIN, A.PROCESS_TYPE AS INIT_PROCESS_TYPE, IP.TEXT2 AS INIT_PROCESS_NAME, A.WAREHOUSE_CODE AS INIT_WAREHOUSE_CODE, IW.TEXT2 AS INIT_WAREHOUSE_NAME, A.BELOW_COMORG_CODE AS INIT_BELOW_COMORG_CODE, CASE WHEN A.BELOW_COMORG_CODE = 'ALL' THEN '전체' ELSE (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BELOW_COMORG_CODE ) END AS INIT_BELOW_COMORG_NAME, NVL(A.KEP_DESCRIPTION, A.DESCRIPTION) AS CMS_DESCRIPTION, NVL(A.KEP_SPECIFICATION, A.SPECIFICATION) AS CMS_SPECIFICATION, NVL(A.KEP_UNIT_MEASURE, A.UNIT_MEASURE) AS CMS_UNIT_MEASURE, NVL(A.KEP_MAKER_NAME, A.MAKER_NAME) AS CMS_MAKER_NAME, NVL(A.KEP_ORIGIN_NAME, A.ORIGIN_NAME) AS CMS_ORIGIN_NAME, NVL(A.KEP_MAKER_PART_NO, A.MAKER_PART_NO) AS CMS_MAKER_PART_NO, NVL(A.KEP_MAKER_CODE, A.MAKER_CODE) AS CMS_MAKER_CODE, NVL(A.KEP_ORIGIN_CODE, A.ORIGIN_CODE) AS CMS_ORIGIN_CODE , NVL(A.KEP_RATE,0) AS KEP_RATE , A.ITEM_MAKE_TYPE , NVL(A.MOQ_QTY,1) AS MOQ_QTY , A.CATEGORY_CHOICE_TYPE , NVL(A.RFQ_IMG_FLAG,'N') AS RFQ_IMG_FLAG , A.RFQ_IMG_TYPE , DECODE(A.RFQ_IMG_TYPE, 'M', A.IMGFILE_DIR, 'N', A.IMGFILE_DIR, B.IMGFILE_DIR) AS IMGFILE_DIR , DECODE(A.RFQ_IMG_TYPE, 'M', A.IMGFILE_NAME, 'N', A.IMGFILE_NAME, B.IMGFILE_NAME) AS IMGFILE_NAME , B.STOA_REMARK , A.TAX_TYPE , B.SELLER_ITEM_NO , A.MAKER_PART_NO , A.DESCRIPTION_ENG , A.SPECIFICATION_ENG , NVL(A.EXP_CODE, ( SELECT MAX(X.TEXT2) FROM ( SELECT TEXT2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'DPAL' AND COD3.BUYER = 'KRKORE0001' AND COD3.CODE1 = A.BUYER AND COD3.TEXT3 LIKE '%'||A.PLANT||'%' AND COD3.FLAG = 'Y' UNION ALL SELECT TEXT2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'DPAL' AND COD3.BUYER = 'KRKORE0001' AND COD3.CODE1 = A.BUYER AND B.SELLER_AREA LIKE '%'||COD3.CODE2||'%' AND COD3.FLAG = 'Y' ) X )) AS EXP_CODE , A.PLANT , B.BID_SUCCESS_REASON , B.SELLER_AREA , A.CONTRACT_INFO , KEP.F_GET_RQDT_PM_FLAG(A.BUYER, A.SG_ID, A.KEP_RATE) AS QTT_CMPY_INFO , A.ASSIGN_AGENT_CODE , A.BTOA_NEGO_PRICE , A.BTOA_USER_ID FROM KEPRQDT A INNER JOIN KEPQTDT B ON (1 = 1 AND B.BUYER = A.BUYER AND B.QUOTATION_NO = A.QUOTATION_NO AND B.QUOTATION_SEQ = A.QUOTATION_SEQ AND B.REVISION = A.REVISION AND B.ATOB_UNIT_PRICE <> 0 AND B.BID_SUCCESS_FLAG = 'Y' AND B.STATUS IN ('C','R') AND NVL(B.STOA_LIST_PRICE, 0) > 0 ) LEFT OUTER JOIN ICOMCMPY BP ON (1 = 1 AND BP.COM_CODE = A.BUYER AND BP.STATUS IN ('C','R') ) LEFT OUTER JOIN ICOMCOD1 MK ON (1 = 1 AND MK.TYPE = 'M104' AND MK.CODE = A.MAKER_CODE AND MK.FLAG = 'Y' ) LEFT OUTER JOIN ICOMCMPY AP ON (1 = 1 AND AP.COM_CODE = B.AGENT AND AP.STATUS IN ('C','R') ) LEFT OUTER JOIN ICOMCOD1 OG ON (1 = 1 AND OG.TYPE = 'M001' AND OG.CODE = A.ORIGIN_CODE AND OG.FLAG = 'Y' ) LEFT OUTER JOIN CMSCATEG CE ON (1 = 1 AND CE.CMS_CATEG_ID = A.CMS_CATEG_ID ) LEFT OUTER JOIN ICOMCOD1 IP ON (1 = 1 AND IP.TYPE = 'M034' AND IP.CODE = A.PROCESS_TYPE AND IP.FLAG = 'Y' ) LEFT OUTER JOIN ICOMCOD1 IW ON (1 = 1 AND IW.TYPE = 'W001' AND IW.TEXT1 = A.WAREHOUSE_CODE AND IW.FLAG = 'Y' ) LEFT OUTER JOIN ICOMBYIT BYIT ON (1 = 1 AND BYIT.BUYER = BP.BYCA_COMORG_CODE AND BYIT.BUYER_ITEM_NO = A.BUYER_ITEM_NO AND BYIT.STATUS IN ('C','R') ) LEFT OUTER JOIN ICOMCQDT CQDT ON (1 = 1 AND CQDT.BUYER = BP.BYCA_COMORG_CODE AND CQDT.BUYER_ITEM_NO = A.BUYER_ITEM_NO AND CQDT.CONTRACT_NO = A.CONTRACT_NO AND CQDT.CONTRACT_SEQ = A.CONTRACT_SEQ AND CQDT.STATUS IN ('C','R') ) LEFT OUTER JOIN ICOMCOD1 PT ON (1 = 1 AND PT.TYPE = 'M034' AND PT.CODE = CQDT.PROCESS_TYPE AND PT.FLAG = 'Y' ) LEFT OUTER JOIN ICOMCMPY OA ON (1 = 1 AND OA.COM_CODE = CQDT.ORIGIN_AGENT AND OA.STATUS IN ('C','R') ) WHERE (A.BUYER||A.QUOTATION_NO||A.QUOTATION_SEQ||A.REVISION) IN
#{item}
AND A.SO_CA_FLAG = 'SO' AND A.ATOB_UNIT_PRICE = 0 AND A.ATOB_SEND_FLAG = 'N' AND A.RECV_FLAG NOT IN ('GD','PM') AND A.STATUS IN ('C','R') ) RFQ LEFT OUTER JOIN ICOMBYCA BYCA ON (1 = 1 AND BYCA.COM_CODE = RFQ.ORG_CODE AND BYCA.STD_CATEG_ID = RFQ.CATEGORY_NO )

