UPDATE KEPQTDT	 /*saveAtosDateQtdt*/  		
 	SET ATOS_END_DATE=#{ATOS_END_DATE}
 		  , ATOS_END_TIME=#{ATOS_END_TIME}	
 		  , LEAD_TIME = #{LEAD_TIME}
 		  , SELLER_AREA = F_GET_SELLER_AREA(#{BUYER},#{PLANT},SELLER_AREA)
   WHERE BUYER=#{BUYER}     
      AND QUOTATION_NO=#{QUOTATION_NO} 
      AND QUOTATION_SEQ=#{QUOTATION_SEQ} 
      AND REVISION=#{REVISION}
	  AND	AGENT=#{AGENT}			
	  AND	STATUS IN ('C','R')

