SELECT/*selectBuyerItemDoubleCheck*/							
		COUNT(*) AS CNT
		, CASE WHEN COUNT(*) >= 1 THEN 'T' ELSE 'F' END DBL_CHK
  FROM ICOMBYIT					
 WHERE BUYER=#{BUYER} 					
	 AND BUYER_ITEM_NO=#{BUYER_ITEM_NO}

