UPDATE KEPRQDT A  /*saveQuotaionRqdt*/ 
    SET KEP_USER_ID        = #{st_user_id},
        ATOB_REMARK        = #{ATOB_REMARK},
        AGENT_OPEN_FLAG    = #{AGENT_OPEN_FLAG},
        SELLER_IMAGE_KEY   = #{SELLER_IMAGE_KEY},
        BUYER_TARGET_PRICE = #{BUYER_TARGET_PRICE},
        PASS_FLAG          = DECODE(NVL(#{PM_FLAG},'N'),'Y','Y','N'),
        ATOB_UNIT_PRICE          = DECODE(NVL(#{PM_FLAG},'N'),'Y',ATOB_UNIT_PRICE,#{ATOB_UNIT_PRICE}),
        MAKER_NAME         = (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M104' AND CODE=#{MAKER_CODE}),
        MAKER_CODE         = #{MAKER_CODE}, 
        ORIGIN_NAME        = (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE='M001' AND FLAG='Y' AND CODE=#{ORIGIN_CODE}),
        ORIGIN_CODE        = #{ORIGIN_CODE},
        UNIT_MEASURE       = #{UNIT_MEASURE},
        KEP_DESCRIPTION    = #{CMS_DESCRIPTION},
        KEP_SPECIFICATION  = #{CMS_SPECIFICATION},
        KEP_UNIT_MEASURE   = #{CMS_UNIT_MEASURE},
        KEP_MAKER_NAME     = #{CMS_MAKER_NAME}, 
        KEP_ORIGIN_NAME    = #{CMS_ORIGIN_NAME},
        KEP_MAKER_PART_NO  = #{CMS_MAKER_PART_NO}, 
        KEP_MAKER_CODE     = #{CMS_MAKER_CODE},
        KEP_ORIGIN_CODE    = #{CMS_ORIGIN_CODE},
        CMS_CATLG_ID       = #{CMS_CATLG_ID}
        , BUYER_ITEM_NO = #{BUYER_ITEM_NO}       
        , CATEGORY_NO = #{BUYER_CATEG_CODE}
    	, PROCESS_TYPE = #{INIT_PROCESS_TYPE}
        , AGENT_NAME = (CASE WHEN #{INIT_PROCESS_TYPE} = '0' OR #{INIT_PROCESS_TYPE} = '2' THEN #{AGENT_NAME}
        	WHEN #{INIT_PROCESS_TYPE} = '1' OR #{INIT_PROCESS_TYPE} = '3' THEN #{INIT_WAREHOUSE_NAME}
          END)
        , CONTRACT_NO = #{CONTRACT_NO}
        , CONTRACT_SEQ = #{CONTRACT_SEQ}
        , BELOW_COMORG_CODE = #{INIT_BELOW_COMORG_CODE}
        , ITEM_GROUP = 'M'
        , ATOB_SEND_FLAG = DECODE(NVL(#{PM_FLAG},'N'), 'Y', 'N', DECODE(#{BUYER_ITEM_NO_STATUS}, '신규', 'N', 'Y'))
        , ITEM_MAKE_TYPE =  #{ITEM_MAKE_TYPE} 
        , MOQ_QTY = #{MOQ_QTY} 
        , MAKER_PART_NO = #{MAKER_PART_NO}
        , DESCRIPTION_ENG = #{DESCRIPTION_ENG}
        , SPECIFICATION_ENG = #{SPECIFICATION_ENG}
        , EXP_CUR = #{EXP_CUR}
        , EXP_CUR_PRICE = #{EXP_CUR_PRICE}
        , EXP_FOR_UNIT_PRICE = #{EXP_FOR_UNIT_PRICE}
        , EXP_KR_UNIT_PRICE = #{EXP_KR_UNIT_PRICE}
        , EXP_INC_EXPENSE = #{EXP_INC_EXPENSE}
        , EXP_CODE = #{EXP_CODE}
        , CONTRACT_INFO = #{CONTRACT_INFO}
        , SELL_CLOSE_DATE = #{TO_DATE}
        , BUY_CLOSE_DATE = #{BUY_CLOSE_DATE}
        , IMGFILE_NAME = #{IMGFILE_NAME}
        , IMGFILE_DIR = #{IMGFILE_DIR}
        , RFQ_IMG_TYPE = #{RFQ_IMG_TYPE}			       
  WHERE BUYER         =#{BUYER}    
    AND QUOTATION_NO  =#{QUOTATION_NO}    
    AND QUOTATION_SEQ =#{QUOTATION_SEQ}    
    AND REVISION      =#{REVISION}    
    AND STATUS IN ('C','R')


			UPDATE KEPMGPDT /*deleteKEPMGPDT*/
				SET STATUS = 'D'            
               , CHANGE_DATE = SYSDATE
			WHERE BUYER = #{BUYER}
			   AND QUOTATION_NO = #{QUOTATION_NO}  
               AND QUOTATION_SEQ = #{QUOTATION_SEQ}     
               AND REVISION = #{REVISION}  
               AND STATUS = 'C'


			UPDATE KEPMGPHD  /*deleteKEPMGPHD*/
				SET STATUS = 'D'            
               , CONFIRM_DATE = SYSDATE  
               , CONFIRM_USER_ID = #{st_user_id} 
               , CHANGE_DATE = SYSDATE
			WHERE (BUYER, PM_NO) IN (SELECT BUYER, PM_NO 
													 FROM KEPMGPDT 
												 WHERE BUYER = #{BUYER}
													 AND QUOTATION_NO = #{QUOTATION_NO}  
										             AND QUOTATION_SEQ = #{QUOTATION_SEQ}     
										             AND REVISION = #{REVISION}
										             AND STATUS = 'C'
									               )


		DELETE ICOMBYIT_ADD /*deleteICOMBYIT_ADD*/
		WHERE BUYER = (SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE=#{BUYER} AND STATUS IN ('C','R')) 
			AND QUOTATION_NO = #{QUOTATION_NO}  
            AND QUOTATION_SEQ = #{QUOTATION_SEQ}     
            AND REVISION = #{REVISION}
		    AND STATUS = 'C'
			AND PRODUCT_CLOSE_FLAG IN ('S','K')


UPDATE KEPRQDT A  /*saveExpQuotaionRqdt*/ 
    SET  EXP_CUR = #{EXP_CUR}
        , EXP_CUR_PRICE = #{EXP_CUR_PRICE}
        , EXP_FOR_UNIT_PRICE = F_GET_EXCHANGE_RATE(#{BUYER}, #{ATOB_UNIT_PRICE}, #{EXP_CODE},'01')
        , EXP_KR_UNIT_PRICE = F_GET_EXCHANGE_RATE(#{BUYER}, #{ATOB_UNIT_PRICE}, #{EXP_CODE},'03')
        , EXP_INC_EXPENSE = F_GET_EXCHANGE_RATE(#{BUYER}, #{ATOB_UNIT_PRICE}, #{EXP_CODE},'02')
        , EXP_CODE = #{EXP_CODE}
  WHERE BUYER         =#{BUYER}    
    AND QUOTATION_NO  =#{QUOTATION_NO}    
    AND QUOTATION_SEQ =#{QUOTATION_SEQ}    
    AND REVISION      =#{REVISION}    
    AND STATUS IN ('C','R')

mapper.select:

/*selectCDNO*/
	SELECT TEXT1  G_LENGTH
		, CASE WHEN TEXT3 = 'BC'
			THEN (
					SELECT NVL(MAX(FLAG),'!')
					FROM   ICOMBYCA
					WHERE  COM_CODE     = #{ORG_CODE}
					AND    STD_CATEG_ID = #{BUYER_CATEG_CODE}
				)
		  ELSE TEXT2
		  END AS  G_PREFIX 
		, TEXT3  G_ITEM_NO_SEQ_FLAG
		, CODE1 BUYER
	FROM ICOMCOD3
	WHERE BUYER = 'KRKORE0001'
	AND   TYPE  = 'CDNO'
	AND   CODE1 = #{ORG_CODE}
	AND   CODE2 = #{BUYER}


/*selectBuyerItemNoByContract*/
SELECT	DECODE(COUNT(*), 0, 'NULL_ITEM_NO', MAX(BUYER_ITEM_NO)) AS BUYER_ITEM_NO
FROM	ICOMCQDT
WHERE	1=1
AND		BUYER = (SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE = #{BUYER} AND STATUS IN ('C','R'))
AND		CONTRACT_NO = #{CONTRACT_NO}
AND		CONTRACT_SEQ = #{CONTRACT_SEQ}
AND		STATUS <> 'D'
